def shortest_distances(n, edges, start):
    import heapq
    graph = [[] for _ in range(n)]
    for left, right, weight in edges:
        graph[left].append((right, weight))
        graph[right].append((left, weight))
    distance = [None] * n
    distance[start] = 0
    heap = [(0, start)]
    while heap:
        current, vertex = heapq.heappop(heap)
        if current != distance[vertex]:
            continue
        for neighbour, weight in graph[vertex]:
            candidate = current + weight
            if distance[neighbour] is None or candidate < distance[neighbour]:
                distance[neighbour] = candidate
                heapq.heappush(heap, (candidate, neighbour))
    return [-1 if value is None else value for value in distance]
